// Minimal parsing - just extract and validate JSON from Gemini
const geminiResponse = $input.first().json;
let rawText;

if (geminiResponse.content?.parts?.[0]?.text) {
  rawText = geminiResponse.content.parts[0].text;
} else if (geminiResponse.text) {
  rawText = geminiResponse.text;
} else {
  rawText = JSON.stringify(geminiResponse);
}

// Remove markdown fences if present
let cleanText = rawText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

// Parse JSON
let strategyData;
try {
  strategyData = JSON.parse(cleanText);
} catch (e) {
  throw new Error('Failed to parse Gemini strategy: ' + e.message);
}

if (!strategyData.sceneBreakdown || strategyData.sceneBreakdown.length === 0) {
  throw new Error('No scene breakdown generated');
}

console.log('✅ Video Strategy:');
console.log('   Pacing:', strategyData.videoStrategy.pacing);
console.log('   Total Scenes:', strategyData.sceneBreakdown.length);
strategyData.sceneBreakdown.forEach(s => {
  console.log(`   Scene ${s.sceneNumber} (${s.type}): ${s.duration}s - ${s.purpose}`);
});

// Pass through data from Merge node
const gridData = $('Merge').all()[0].json;
const characterData = $('Merge').all()[1].json;
const formData = $('ParseFormData').first().json;

return [{
  json: {
    videoStrategy: strategyData.videoStrategy,
    sceneBreakdown: strategyData.sceneBreakdown,
    resourceRequirements: strategyData.resourceRequirements,
    productionNotes: strategyData.productionNotes,

    // Pass through from Merge
    productImages: gridData.images,
    productInfo: gridData.product,
    characterImageUrl: characterData.characterImageUrl,
    characterPhysical: characterData.characterPhysical,
    characterConsistency: characterData.consistencyChecklist,
    ugcCreatorProfile: gridData.ugcCreatorProfile,
    videoProductionMetadata: gridData.videoProductionMetadata,

    // Pass through from form
    productName: formData.productName,
    productDescription: formData.productDescription,
    targetAudience: formData.targetAudience,
    ugcStyleDetails: formData.ugcStyleDetails,
    additionalNotes: formData.additionalNotes,

    timestamp: new Date().toISOString(),
    status: 'video_strategy_ready',
    progress: 50
  }
}];

