// Minimal parsing - extract and validate scene prompts
const geminiResponse = $input.first().json;
let rawText;

if (geminiResponse.content?.parts?.[0]?.text) {
  rawText = geminiResponse.content.parts[0].text;
} else if (geminiResponse.text) {
  rawText = geminiResponse.text;
} else {
  rawText = JSON.stringify(geminiResponse);
}

let cleanText = rawText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

let sceneData;
try {
  sceneData = JSON.parse(cleanText);
} catch (e) {
  throw new Error('Failed to parse scene prompts: ' + e.message);
}

if (!sceneData.scenes || sceneData.scenes.length === 0) {
  throw new Error('No scenes generated');
}

console.log('✅ Scene Prompts Ready:', sceneData.scenes.length, 'scenes');

const previousData = $('Parse Strategy').first().json;

return [{
  json: {
    scenes: sceneData.scenes,
    characterReference: sceneData.characterReference,
    productIntegration: sceneData.productIntegration,
    fullVideoScript: sceneData.fullVideoScript,
    videoStrategy: previousData.videoStrategy,
    productImages: previousData.productImages,
    characterImageUrl: previousData.characterImageUrl,
    timestamp: new Date().toISOString(),
    status: 'scene_prompts_ready',
    progress: 60
  }
}];

// Split scenes into individual items for loop processing
const sceneData = $input.first().json;
const scenes = sceneData.scenes;

const output = scenes.map(scene => ({
  json: {
    currentScene: scene,
    characterReference: sceneData.characterReference,
    productIntegration: sceneData.productIntegration,
    videoStrategy: sceneData.videoStrategy,
    productImages: sceneData.productImages,
    nanoBananaConfig: {
      model: 'nano-banana-pro',
      aspectRatio: scene.technicalSpecs.aspectRatio,
      resolution: '2K',
      outputFormat: 'png'
    },
    totalScenes: scenes.length,
    timestamp: new Date().toISOString()
  }
}));

console.log('✅ Prepared', output.length, 'scenes for generation');
return output;

// Extract scene image URL from API response
const kieResponse = $json;
const sceneContext = $('Split Scenes').item.json;

if (kieResponse.data.state !== 'success') {
  throw new Error('Scene generation failed');
}

const resultJson = JSON.parse(kieResponse.data.resultJson);
const sceneImageUrl = resultJson.resultUrls[0];

if (!sceneImageUrl) {
  throw new Error('No image URL in response');
}

const scene = sceneContext.currentScene;

console.log('✅ Scene', scene.sceneNumber, 'ready:', sceneImageUrl);

return [{
  json: {
    sceneNumber: scene.sceneNumber,
    sceneType: scene.type,
    duration: scene.duration,
    startTime: scene.startTime,
    endTime: scene.endTime,
    productVisible: scene.productVisible,
    emotionalTone: scene.emotionalTone,
    imageUrl: sceneImageUrl,
    script: scene.script,
    technicalSpecs: scene.technicalSpecs,
    taskId: kieResponse.data.taskId,
    generationTime: kieResponse.data.costTime,
    timestamp: new Date().toISOString(),
    status: 'scene_image_ready'
  }
}];

// Parse final compilation from Gemini
const geminiResponse = $input.first().json;
let rawText;

if (geminiResponse.content?.parts?.[0]?.text) {
  rawText = geminiResponse.content.parts[0].text;
} else if (geminiResponse.text) {
  rawText = geminiResponse.text;
} else {
  rawText = JSON.stringify(geminiResponse);
}

let cleanText = rawText.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

let compilationData;
try {
  compilationData = JSON.parse(cleanText);
} catch (e) {
  throw new Error('Failed to parse final compilation: ' + e.message);
}

console.log('✅ Final Compilation Ready');
console.log('   Quality:', compilationData.productionSummary.estimatedFinalQuality);
console.log('   Ready for video gen:', compilationData.productionSummary.readyForVideoGeneration);
if (compilationData.qualityCheck.concerns?.length > 0) {
  console.log('⚠️  Concerns:', compilationData.qualityCheck.concerns);
}

return [{
  json: {
    finalScenes: compilationData.finalScenes,
    fullVideoScript: compilationData.fullVideoScript,
    qualityCheck: compilationData.qualityCheck,
    videoGenerationQueue: compilationData.videoGenerationQueue,
    productionSummary: compilationData.productionSummary,
    timestamp: new Date().toISOString(),
    status: 'all_scenes_ready_and_polished',
    progress: 80
  }
}];

// ===== VIDEO GENERATION PLACEHOLDER =====
// TODO: Implement video generation using seedance-1-5-pro or veo3.1

const finalData = $input.first().json;
const videoQueue = finalData.videoGenerationQueue;

console.log('⏸️ VIDEO GENERATION PLACEHOLDER');
console.log('   Scenes ready:', videoQueue.length);
console.log('   Quality check:', finalData.qualityCheck.characterConsistency);
console.log('   Director notes:', finalData.productionSummary.directorNotes);
console.log('');
console.log('📋 TODO: Implement Video Generation');
console.log('   1. Choose model: seedance-1-5-pro (12s max) or veo3.1 (8s max)');
console.log('   2. Loop through videoGenerationQueue');
console.log('   3. For each scene: Call video API → Wait → Extract URL');
console.log('   4. Collect all video clips');

return [{
  json: {
    ...finalData,
    videoClips: null,
    status: 'video_generation_pending',
    progress: 85,
    placeholderNote: 'Video generation not implemented. Choose model and implement API calls.'
  }
}];

// ===== FFMPEG ASSEMBLY PLACEHOLDER =====
const data = $input.first().json;

console.log('⏸️ FFMPEG ASSEMBLY PLACEHOLDER');
console.log('   Director Quality Assessment:', data.productionSummary.estimatedFinalQuality);
console.log('');
console.log('📋 TODO: Implement FFmpeg');
console.log('   1. Download all video clips');
console.log('   2. Create concat file');
console.log('   3. Run: ffmpeg -f concat -safe 0 -i filelist.txt -c copy final.mp4');

return [{
  json: {
    ...data,
    finalVideoUrl: null,
    status: 'assembly_pending',
    progress: 90
  }
}];

// ===== SUPABASE UPLOAD PLACEHOLDER =====
const data = $input.first().json;

console.log('⏸️ SUPABASE UPLOAD PLACEHOLDER');
console.log('   Final Quality:', data.productionSummary.estimatedFinalQuality);
console.log('');
console.log('📋 TODO: Upload to Supabase Storage + Update video_jobs table');

return [{
  json: {
    success: false,
    status: 'upload_pending',
    progress: 95,
    qualityAssessment: data.productionSummary,
    implementationNeeded: [
      'Upload to Supabase Storage',
      'Update video_jobs table',
      'Error handling with refunds'
    ]
  }
}];
